import csv,json,pathlib,collections,hashlib,datetime
import numpy as np
out=pathlib.Path('outputs');ref=[x for x in csv.DictReader(open(out/'stage5_smad5_splice_snp_ld_reference_coverage.csv')) if x['status']=='unique allele match'];fam=[x.split()[1] for x in open('work/stage4_magma_reference/g1000_eur.fam')];assert len(fam)==len(set(fam))==503;N=len(fam);step=(N+3)//4;bed=np.memmap('work/stage4_magma_reference/g1000_eur.bed',mode='r',dtype='uint8');assert bytes(bed[:3])==bytes([108,27,1]);idx=np.array([int(x['bim_index_zero_based']) for x in ref],dtype=np.int64);offset=3+idx[:,None]*step+np.arange(step)[None,:];b=bed[offset];code=((b[:,:,None]>>np.array([0,2,4,6],dtype=np.uint8))&3).reshape(len(ref),-1)[:,:N];decode=np.array([2.,np.nan,1.,0.]);G=decode[code].T;altflip=np.array([x['bim_a1']!=x['alt38'] for x in ref]);G[:,altflip]=2-G[:,altflip]
ind=collections.defaultdict(dict)
for x in csv.DictReader(open(out/'stage5_smad5_indel_reference_eur_dosages.csv')):ind[x['variant_GRCh38']][x['sample']]=float(x['alt_dosage']) if x['alt_dosage'] else np.nan
assert all(set(v)==set(fam) for v in ind.values());labels=[x['variant_GRCh38'] for x in ref]+list(ind);G=np.column_stack([G]+[np.array([v[s] for s in fam]) for v in ind.values()]);assert len(labels)==len(set(labels))==G.shape[1]
missing=np.isnan(G).sum(axis=0);means=np.nanmean(G,axis=0);G=np.where(np.isnan(G),means[None,:],G);sd=np.std(G,axis=0);keep=np.isfinite(sd)&(sd>0);removed=[labels[i] for i in np.flatnonzero(~keep)];G=G[:,keep];means=means[keep];sd=sd[keep];missing=missing[keep];labels=[k for k,z in zip(labels,keep) if z];Z=(G-means)/sd;R=(Z.T@Z/N).astype('float32');assert np.max(np.abs(R-R.T))<1e-6 and np.max(np.abs(np.diag(R)-1))<1e-6
np.savez_compressed(out/'stage5_smad5_muscle_eur_reference_ld.npz',r=R,variant=np.asarray(labels),n_samples=np.int32(N))
with open(out/'stage5_smad5_muscle_eur_ld_variant_order.csv','w',newline='') as f:
 w=csv.writer(f);w.writerow(['matrix_index_zero_based','variant_GRCh38_ref_alt','alt_frequency_EUR','missing_genotypes','reference_source']);
 for i,(k,mean,miss) in enumerate(zip(labels,means,missing)):w.writerow([i,k,mean/2,int(miss),'1000G phase3 indel VCF' if k in ind else 'MAGMA 1000G EUR BIM/BED'])
receipt={'created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'samples':N,'snvs_unique_bim_matches':len(ref),'indels_public_vcf':len(ind),'variants_retained':len(labels),'monomorphic_removed':removed,'reference_ld_rank_upper_bound':N-1,'matrix_sha256':hashlib.sha256((out/'stage5_smad5_muscle_eur_reference_ld.npz').read_bytes()).hexdigest(),'order_sha256':hashlib.sha256((out/'stage5_smad5_muscle_eur_ld_variant_order.csv').read_bytes()).hexdigest(),'method':'ALT dosage, per-variant mean imputation for missing genotypes, Pearson correlation; samples matched by ID','scope':'EUR reference only, partial locus coverage, missing one credible-set indel; no SuSiE or colocalization run'};(out/'stage5_smad5_muscle_eur_ld_receipt.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps(receipt,indent=2))
